import{_ as e,o as r,c as t,S as o}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"前端开发中的加载性能优化","description":"不同于需要安装的安卓 App 或者 iOS App，前端 App 所有的资源文件都要通过网络进行下载，所以加载速度越快对用户的体验来说就越好。因为我们也需要在加载的时候进行优化，减少不必要的资源请求。","frontmatter":{"title":"前端开发中的加载性能优化","date":"2020-12-20 10:48","comments":true,"archives":2020,"tags":["web","performance"]},"headers":[],"relativePath":"posts/2020-12-20-loading-performance/index.md","filePath":"posts/2020/2020-12-20-loading-performance.md"}'),n={name:"posts/2020-12-20-loading-performance/index.md"};function h(i,a,l,p,s,d){return r(),t("div",null,[...a[0]||(a[0]=[o('<p>不同于需要安装的安卓 App 或者 iOS App，前端 App 所有的资源文件都要通过网络进行下载，所以加载速度越快对用户的体验来说就越好。因为我们也需要在加载的时候进行优化，减少不必要的资源请求。</p><h2 id="文本内容的优化" tabindex="-1">文本内容的优化 <a class="header-anchor" href="#文本内容的优化" aria-label="Permalink to &quot;文本内容的优化&quot;">​</a></h2><h3 id="压缩代码" tabindex="-1">压缩代码 <a class="header-anchor" href="#压缩代码" aria-label="Permalink to &quot;压缩代码&quot;">​</a></h3><p>HTML，JS，CSS 都有相应的工具可以进行代码压缩，可以使用 webpack 工具方便的进行代码压缩。JS 使用工具<a href="https://github.com/terser/terser" target="_blank" rel="noreferrer">terser</a>，CSS 使用<a href="https://github.com/cssnano/cssnano" target="_blank" rel="noreferrer">CSS Nano</a>, HTML 使用<a href="https://github.com/kangax/html-minifier" target="_blank" rel="noreferrer">HTMLMinifier</a>进行代码压缩。</p><h3 id="使用-gzip-进行压缩" tabindex="-1">使用 GZIP 进行压缩 <a class="header-anchor" href="#使用-gzip-进行压缩" aria-label="Permalink to &quot;使用 GZIP 进行压缩&quot;">​</a></h3><p>现代化浏览器都支持 GZIP 进行压缩，并且服务器端 NGINX 也可以很方便的配置使用 GZIP 压缩请求的资源文件。</p><h3 id="减少第三方-js-的引用" tabindex="-1">减少第三方 JS 的引用 <a class="header-anchor" href="#减少第三方-js-的引用" aria-label="Permalink to &quot;减少第三方 JS 的引用&quot;">​</a></h3><p>在 2010 年左右，人们都爱使用 jQuery 框架进行开发，因为 jQuery 抹平了浏览器之间的差异性，大大提高了开发效率。但随着浏览器吸收了 jQuery 的各种优点，例如可以使用<code>document.querySelector</code>很方便的像 jQuery 一样选择元素。现在的前端开发已经不那么需要 jQuery 了，你可以访问<a href="http://youmightnotneedjquery.com/" target="_blank" rel="noreferrer">You might not need jQuery</a>来查找替代的方法。</p><h3 id="webpack-相关的优化" tabindex="-1">webpack 相关的优化 <a class="header-anchor" href="#webpack-相关的优化" aria-label="Permalink to &quot;webpack 相关的优化&quot;">​</a></h3><p>可以使用 webpack 的<a href="https://webpack.js.org/plugins/split-chunks-plugin/" target="_blank" rel="noreferrer">SplitChunksPlugin</a>， 分割 JS 文件，只打包首次载入需要的 JS 文件来减少网络请求。 我们也可以使用<a href="https://webpack.js.org/guides/tree-shaking/" target="_blank" rel="noreferrer">Tree Shaking</a>来引入需要的 JS 库，避免不使用的代码被打包进来。</p><h2 id="图像内容的优化" tabindex="-1">图像内容的优化 <a class="header-anchor" href="#图像内容的优化" aria-label="Permalink to &quot;图像内容的优化&quot;">​</a></h2><h3 id="移除不使用的图像" tabindex="-1">移除不使用的图像 <a class="header-anchor" href="#移除不使用的图像" aria-label="Permalink to &quot;移除不使用的图像&quot;">​</a></h3><p>由于网站项目的更新，很多时候有一些不被使用的图像资源被打包进输出目录。这样会导致无谓的资源加载，需要及时发现和删除。</p><h3 id="选择合适的图像格式" tabindex="-1">选择合适的图像格式 <a class="header-anchor" href="#选择合适的图像格式" aria-label="Permalink to &quot;选择合适的图像格式&quot;">​</a></h3><p>众所周知，png 图像可以展示透明效果，但是 jpg 图像做不到。但是因为 png 比 jpg 多了一个 alpha 通道，所以占用的空间也大，如果不需要透明效果展示，相同的图像效果，jpg 会占用更小的空间。</p><h3 id="移除图像的-metadata" tabindex="-1">移除图像的 Metadata <a class="header-anchor" href="#移除图像的-metadata" aria-label="Permalink to &quot;移除图像的 Metadata&quot;">​</a></h3><p>图像的 Metadata 对于 web 资源来说并没有什么意义，所以移除 Metadata 可以减少图像占用空间。</p><h3 id="调整图像尺寸" tabindex="-1">调整图像尺寸 <a class="header-anchor" href="#调整图像尺寸" aria-label="Permalink to &quot;调整图像尺寸&quot;">​</a></h3><p>如果显示的尺寸和实际尺寸差距过大，也会造成不必要的资源浪费。</p><h3 id="调整图像质量" tabindex="-1">调整图像质量 <a class="header-anchor" href="#调整图像质量" aria-label="Permalink to &quot;调整图像质量&quot;">​</a></h3><p>在很多情况下，对图像质量没有过高的要求，可以损失质量来换取更小的空间。</p><h3 id="压缩图像" tabindex="-1">压缩图像 <a class="header-anchor" href="#压缩图像" aria-label="Permalink to &quot;压缩图像&quot;">​</a></h3><p>现在有很多算法可以有损或者无损的压缩图像，在发布之前，可以使用压缩工具减少图像的使用空间。</p><h2 id="http-请求优化" tabindex="-1">HTTP 请求优化 <a class="header-anchor" href="#http-请求优化" aria-label="Permalink to &quot;HTTP 请求优化&quot;">​</a></h2><p>可以使用 HTTP2 协议来提高网站的载入速度，HTTP2 允许多路复用，多个请求可以使用单一的 HTTP 连接来处理，大大提高了载入速度。 这里有一个<a href="https://http2.akamai.com/demo" target="_blank" rel="noreferrer">demo</a> 大家可以使用浏览器打开，感受一下。</p><h2 id="http-cache" tabindex="-1">HTTP Cache <a class="header-anchor" href="#http-cache" aria-label="Permalink to &quot;HTTP Cache&quot;">​</a></h2><p>可以通过缓存技术来提高网站的载入速度，当用户再次访问网站的时候可以直接使用缓存而不必再次请求资源文件。我们甚至可以使用<a href="https://developers.google.com/web/fundamentals/primers/service-workers" target="_blank" rel="noreferrer">Service Workers</a>缓存整个网站，保证可以离线使用。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>载入优化需要从各个方面入手，查找分析前端 App 的资源文件，并从网络请求和缓存下手才能达到最优的效果。</p><h2 id="参考" tabindex="-1">参考 <a class="header-anchor" href="#参考" aria-label="Permalink to &quot;参考&quot;">​</a></h2><p><a href="https://developers.google.com/web/fundamentals/performance/get-started" target="_blank" rel="noreferrer">Loading Performance</a></p>',31)])])}const b=e(n,[["render",h]]);export{u as __pageData,b as default};
